INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}, {"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "冯国胜", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "吴将，参与伏击陈友谅及追击战。", "biography": null, "status": "draft", "id": "11681f87-f6f7-58db-93b2-dad66d159d27"}, {"name": "蓝玉", "aliases": ["藍玉"], "era": "明", "birth_year": null, "death_year": null, "description": "明初将领。本纪载其以都督身份随西平侯沐英征讨西番。", "biography": null, "status": "draft", "id": "b9acd0d9-69b0-5100-b509-064627c8b88a"}, {"name": "朱标", "aliases": ["朱標"], "era": "明", "birth_year": null, "death_year": null, "description": "明太祖时的皇太子。本纪记其于洪武二十五年去世。", "biography": null, "status": "draft", "id": "5c5e855f-d901-54a9-80ba-9dfe24f7c9f9"}, {"name": "沐英", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "定远人，父母亡，朱元璋收养、赐朱姓。", "biography": null, "status": "draft", "id": "c9e9d78a-2557-5892-876e-b1e99dd22bed"}, {"name": "周德兴", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "吴后明左丞，1367年奉命取广西，1368年取全州。", "biography": null, "status": "draft", "id": "b38e5f86-1f46-53af-90e5-784532a2661c"}, {"name": "傅友德", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "原陈友谅小孤山守将，1361年降吴。", "biography": null, "status": "draft", "id": "052c6ab9-234a-5d89-9bad-ec31f6774b50"}, {"name": "朱允炆", "aliases": ["明惠帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明惠帝。洪武31年（年号对照1398年），本表记录了朱允炆的活动。", "biography": null, "status": "draft", "id": "76ea9485-acac-508c-a6ae-e2532462c03e"}, {"name": "詹徽", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，洪武17年（年号对照1384年）正月，詹徽出任左都御史。", "biography": null, "status": "draft", "id": "a89bb9a2-cd82-5e5d-befc-d22bbdc609f2"}, {"name": "耿炳文", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年随朱元璋于和州。", "biography": null, "status": "draft", "id": "348f31d6-f709-5dde-a5f7-f84796bfa663"}]'::jsonb)
