: null, "status": "draft", "id": "86ddc276-75b2-5abe-ae02-e9c3e1f44bc3"}, {"title": "晋王燕王等四王来朝", "description": "晋王朱棡、燕王朱棣、楚王朱桢和湘王朱柏来朝。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年正月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7f77580c-9ac6-5f38-a418-c38225941960"}, {"title": "朝廷召李景隆等回京", "description": "朝廷下令召曹国公李景隆等返回京师。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年二月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "34479376-3bc5-5130-8fef-c72a2e5a547b"}, {"title": "叶昇等人在河南及西北若干地方练兵", "description": "靖宁侯叶昇等在河南和本纪所列的临、巩、甘、凉、延庆等地练兵。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "81625270-22d9-5ce1-b3e7-a1618885c3cc"}, {"title": "本纪记茅鼎等平定五开战事", "description": "本纪在二月条记都督茅鼎等人平定五开战事。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e2ed77bc-b946-54af-926f-780f4c1549e0"}, {"title": "朱元璋行耕耤礼", "description": "朱元璋举行亲耕耤田的仪式。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年二月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "32e542be-8692-5484-9a66-72128d3d0fcd"}, {"title": "明廷下诏各卫所七成军士屯田", "description": "朝廷下诏，各地卫所用十分之七的军士从事屯田。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年二月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ac35b415-9b35-5b30-a717-ca650dca341d"}, {"title": "冯胜等人分管陕西山西河南各卫军务", "description": "冯胜等十四人分别掌理陕西、山西和河南各卫的军务。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年三月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "af74c1b3-f3d4-5e29-a195-6a6ede6e139d"}, {"title": "明廷改封豫王汉王卫王", "description": "朝廷将豫王朱桂改封代王、汉王朱楧改封肃王、卫王朱植改封辽王。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年三月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "705da85f-2bac-5e70-b215-831ffd1473d3"}, {"title": "蓝玉出兵罕东", "description": "凉国公蓝玉出兵征讨罕东。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年四月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c9e2b364-67ab-5730-af45-3457f759557f"}, {"title": "月鲁帖木儿起兵，鲁毅击败来军", "description": "建昌卫指挥月鲁帖木儿起兵反明，指挥鲁毅率部将其击败。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年四月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d6841da0-8dc4-5d2b-8f30-3e9b788d5b0a"}, {"title": "皇太子朱标去世", "description": "本纪记载，皇太子朱标于四月丙子去世。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年四月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f929b2d6-cc37-5057-a899-cf4ef6bcc5c1"}, {"title": "明廷命聂纬等讨月鲁帖木儿", "description": "明廷命都督聂纬、徐司马和瞿能率军征讨月鲁帖木儿，并命蓝玉返回后由他统一指挥。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年四月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "961df34b-75be-5d32-8b4d-0f80fb8b8fac"}, {"title": "蓝玉到达罕东后转赴建昌", "description": "蓝玉抵达罕东，对方逃走。蓝玉随即率军前往建昌。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年五月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1b9a5c15-7d07-517b-90fb-c94794ed95e9"}, {"title": "明廷赈济陈州原武水灾", "description": "明廷下令赈济陈州、原武水灾。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年五月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7bbb58b0-869c-519a-9def-6ca00b035e33"}, {"title": "西平侯沐英在云南去世", "description": "西平侯沐英在云南去世。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年六月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "be86abd5-e51a-5766-83a7-b13b7a3efd01"}, {"title": "秦王朱樉返回封国", "description": "秦王朱樉于七月庚辰回到封国。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年七月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c7dace82-7159-5590-82ee-cd42ec85fa55"}, {"title": "瞿能在双狼寨击败月鲁帖木儿", "description": "指挥瞿能在双狼寨率军击败月鲁帖木儿。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年七月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "524c8e25-90cd-58f0-b76e-ea60280fe80b"}, {"title": "江夏侯周德兴被处死", "description": "江夏侯周德兴获罪被处死，本纪这一句未列具体罪名。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年八月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7564b72f-3630-5ff0-82d3-7037fa725c5b"}, {"title": "冯胜傅友德等在山西扩充军籍并设卫屯田", "description": "冯胜、傅友德率开国公常昇等分赴山西各处，将民户登记入军籍，在大同、东胜屯田，并设立十六卫。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年八月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "42c8c6de-bc8d-5a38-81ce-7baf490ca495"}, {"title": "明廷给公侯岁禄并将赐田收归官府", "description": "朝廷按年给公侯发放俸禄，将原先所赐田地收归官府。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年八月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3155a520-3f7b-54a8-a292-5469d185b9d8"}, {"title": "靖宁侯叶昇因涉胡惟庸案被处死", "description": "本纪记载，靖宁侯叶昇被定为胡惟庸同党并处死。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年八月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5de16476-12e7-50f9-9adf-7140840987bf"}, {"title": "朱允炆被立为皇太孙", "description": "朱元璋立皇孙朱允炆为皇太孙。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年九月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a74b307e-2cb9-5f99-b49e-8e21a3b4c7c2"}, {"title": "本纪记李成桂自立并记朝鲜更号", "description": "本纪记载，高丽李成桂幽禁君主瑶并自立，随后凭高丽国人的表文向明廷请命。明廷准许，其国号后来改为朝鲜。", "start_year": null, "end_year": null, "time_original": "参见本纪洪武二十五年条；各阶段原文未各标具体年月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "712bc355-d8d8-5281-8ef7-96189c00d512"}, {"title": "沐春袭封西平侯并镇守云南", "description": "沐春承袭西平侯的封爵，镇守云南。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年十月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "03737d99-650b-52b6-b773-2c933c66dd9b"}, {"title": "蓝玉擒杀月鲁帖木儿后奉召返回", "description": "蓝玉擒获并处死月鲁帖木儿。朝廷下令召回蓝玉。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年十一月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c8370a6c-bc7b-5b44-a136-9673cfe022be"}, {"title": "冯胜傅友德等兼任东宫师保官", "description": "宋国公冯胜和颍国公傅友德等人兼任东宫的师保官。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十五年十二月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c94dfac0-a4f0-56ab-8b29-daea30360475"}, {"title": "冯胜与傅友德奉命在山西河南练兵", "description": "冯胜任总兵官，傅友德为副，在山西、河南练兵，并兼管屯卫。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十五年闰十二月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "27f3eeac-ba3b-55f0-82d6-41aaf3d9866a"}, {"title": "琉球中山山南等地来贡", "description": "本纪记载，琉球的中山和山南，以及高丽、哈梅里在这一年入贡。 按原历纪年，事情发生在公元1392至1393年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十五年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cabe1372-abb7-566b-ac9e-06ab978eaf53"}, {"title": "明廷免各地老年百姓来朝", "description": "朝廷免去各地老年百姓来朝的要求。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年正月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fc2bcb3d-e97d-5545-b9f1-dedb124fd6cf"}, {"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年正月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6c63c893-b645-53bd-bd8c-8339dd6ba8c7"}, {"title": "晋王朱棡领兵出塞，朝廷召回冯胜等", "description": "晋王朱棡统率山西、河南两地部队出塞。朝廷召冯胜、傅友德、常昇、王弼等返回。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年二月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c7d726e2-b75e-5052-8d48-e91733e76fe8"}, {"title": "蜀王朱椿入朝", "description": "本纪记载，蜀王朱椿在二月乙酉入朝。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年二月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "50610923-5da3-5d52-a464-aa858202d1c4"}, {"title": "蓝玉等人在谋反案中被处死", "description": "本纪记载，凉国公蓝玉被朝廷以谋反罪处死。鹤庆侯张翼、普定侯陈桓、景川侯曹震、舳舻侯朱寿、东莞伯何荣和吏部尚书詹徽等人也因涉案被处死。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "37f213e5-35d0-5f32-aa28-984b0fd64929"}, {"title": "詹徽因罪被处死", "description": "洪武26年（年号对照1393年）二月，詹徽因罪被处死。", "start_year": 1393, "end_year": 1393, "time_original": "洪武26年（年号对照1393年）二月；公元年核为1393年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "c78740ef-e565-5862-96ee-0a099e43e347"}, {"title": "明廷向天下颁布《逆臣录》", "description": "本纪记载，朝廷向各地颁布《逆臣录》。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年二月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9cc67ed5-ffc7-525a-b7fb-a3bab5328fae"}, {"title": "朱元璋行耕耤礼", "description": "朱元璋举行亲耕耤田的仪式。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年二月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bac807d4-1b2c-5868-a56a-556df396de5a"}, {"title": "代王朱桂率护卫兵随晋王出塞", "description": "代王朱桂率护卫军出塞，并受晋王节制。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年三月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6e3114c1-d383-51fc-9568-323fb2fa18eb"}, {"title": "耿炳文在陕西练兵", "description": "长兴侯耿炳文在陕西训练军队。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0aec0d83-640b-5581-a8a8-557b545a9252"}, {"title": "冯胜傅友德在山西和北平备边", "description": "冯胜、傅友德在山西和北平布置边防，其所辖卫将校听从晋王和燕王节制。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年三月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bb1b89a4-12fb-513b-9a3c-f74f8f615694"}, {"title": "明廷准晋王燕王自行处理一般军务", "description": "朝廷下诏，晋王、燕王遇到重大军务才须上报。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年三月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8fe07d2c-cf62-5a45-831e-08ea423df49f"}, {"title": "会宁侯张温因涉蓝玉案被处死", "description": "本纪记载，会宁侯张温被定为蓝玉同党并处死。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年三月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0cdc2dae-8c8a-501a-aa81-70b170e96e2f"}, {"title": "明廷开仓救济孝感并规定遇饥先贷后报", "description": "孝感发生饥荒，朝廷派使者经驿传前往开仓借粮给饥民，并下诏此后遇到饥荒先借粮救济，再向朝廷报告。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年四月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "28001376-adfb-508d-9975-eeafbada32ea"}, {"title": "周王朱橚入朝", "description": "周王朱橚于四月戊子入朝。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年四月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d5c30fd7-0257-5dc9-91d3-4870c52bec4b"}, {"title": "明廷因旱灾诏求直言并复查囚案", "description": "当地发生旱灾，朝廷命群臣直言时政得失，并检查在押囚犯的案件。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年四月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8cc2002a-dab1-54c7-bea1-57faa896532d"}, {"title": "明廷停止接受安南朝贡", "description": "明廷以安南自行废立君主为由，停止接受其朝贡。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年四月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6c59bd9a-1b00-5743-a864-83af70313550"}, {"title": "本纪记七月初一日食", "description": "本纪记载，七月初一出现日食。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年七月甲辰朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "810afd76-f6d3-5fb1-aac9-710ec3623b93"}, {"title": "明廷选张宗濬等人轮值侍奉皇太孙", "description": "朝廷挑选秀才张宗濬等人随詹事府官员轮流在文华殿值班，侍奉皇太孙。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年七月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2e4118d3-8084-5764-aa6a-cdbc3e0cb92c"}, {"title": "秦王燕王等五王入朝", "description": "秦、晋、燕、周、齐五位藩王在八月入朝。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3d0d2043-c179-5aca-8592-c0f4cacdbf0a"}, {"title": "代王肃王等五王入朝", "description": "代、肃、辽、庆、宁五位藩王在九月癸丑入朝。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年九月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3cc78393-f648-57cf-b79b-8a9c4a8438f8"}, {"title": "明廷赦免被定为胡惟庸蓝玉余党的人员", "description": "朝廷赦免被列为胡惟庸、蓝玉余党的人员。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "54b6d31e-8197-5197-8d6c-6dc36489c195"}, {"title": "明廷擢国子监六十四人为布政使等官", "description": "朝廷提拔六十四名国子监生担任布政使等官职。", "start_year": 1393, "end_year": 1393, "time_original": "洪武二十六年十月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cf5e551c-4bd5-54ca-8879-d7df9fe9c7b0"}, {"title": "明廷向诸王颁发《永鉴录》", "description": "朝廷在十二月向各藩王颁发《永鉴录》。", "start_year": 1394, "end_year": 1394, "time_original": "洪武二十六年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8f6a2e01-6498-5f1d-9bf3-1f93686f1379"}, {"title": "琉球爪哇暹罗遣使来贡", "description": "本纪记载，琉球、爪哇和暹罗于这一年向明廷入贡。 按原历纪年，事情发生在公元1393至1394年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十六年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "210c0b07-334a-5814-8372-72337e646747"}]'::jsonb)
